// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! The GUMBO contract checks of every thread: IEP_Post at initialization, CEP_Pre
//! when a thread is about to be dispatched, and CEP_Post when it completes, against
//! the pre-state saved at dispatch.

use data::*;
use crate::{Event, SystemView, ViolationSink};
use crate::gumbox::producer_producer_containers::*;
use crate::gumbox::consumer_consumer_containers::*;

pub struct ComponentContracts {
  /// When set, a dispatch whose CEP_Pre failed is excused from its CEP_Post
  /// (reported as CepPostExcused instead of being checked).  GUMBO is
  /// assume-guarantee: a component owes nothing when its assumptions fail.
  /// The monitor PDs leave it off.
  pub excuse_post_on_failed_pre: bool,
  pre_producer_producer: Option<PreState_producer_producer>,
  pre_ok_producer_producer: bool,
  pre_consumer_consumer: Option<PreState_consumer_consumer>,
  pre_ok_consumer_consumer: bool,
}

impl ComponentContracts {
  pub const fn new() -> Self {
    ComponentContracts {
      excuse_post_on_failed_pre: false,
      pre_producer_producer: None,
      pre_ok_producer_producer: true,
      pre_consumer_consumer: None,
      pre_ok_consumer_consumer: true,
    }
  }

  /// Initialization guarantees, checked once every thread has initialized and
  /// before any has computed.
  pub fn on_init<V: SystemView, S: ViolationSink>(&mut self, s: &mut V, out: &mut S) {
    {
      let post_producer_producer = PostState_producer_producer {
        api_p_myArrayInt32_EventDataPort: s.get_producer_producer_p_myArrayInt32_EventDataPort(),
        api_p_myArrayStruct_EventDataPort: s.get_producer_producer_p_myArrayStruct_EventDataPort(),
        api_p_myStructArray_EventDataPort: s.get_producer_producer_p_myStructArray_EventDataPort(),
        api_p_myArrayInt32_DataPort: s.get_producer_producer_p_myArrayInt32_DataPort(),
        api_p_myArrayStruct_DataPort: s.get_producer_producer_p_myArrayStruct_DataPort(),
        api_p_myStructArray_DataPort: s.get_producer_producer_p_myStructArray_DataPort(),
      };
      if !crate::gumbox::producer_producer_GUMBOX::initialize_IEP_Post(
        post_producer_producer.api_p_myArrayInt32_EventDataPort, post_producer_producer.api_p_myArrayStruct_EventDataPort, post_producer_producer.api_p_myStructArray_EventDataPort, post_producer_producer.api_p_myArrayInt32_DataPort, post_producer_producer.api_p_myArrayStruct_DataPort, post_producer_producer.api_p_myStructArray_DataPort) {
        out.report(crate::Event::IepPostViolation { thread: "producer_producer", post: &post_producer_producer });
      }
    }
  }

  /// `prev` has completed a dispatch: check its CEP_Post against the pre-state
  /// saved when it was dispatched.
  pub fn on_complete<V: SystemView, S: ViolationSink>(&mut self, prev: crate::Thread, s: &mut V, out: &mut S) {
    match prev {
      crate::Thread::producer_producer => {
        let post = PostState_producer_producer {
          api_p_myArrayInt32_EventDataPort: s.get_producer_producer_p_myArrayInt32_EventDataPort(),
          api_p_myArrayStruct_EventDataPort: s.get_producer_producer_p_myArrayStruct_EventDataPort(),
          api_p_myStructArray_EventDataPort: s.get_producer_producer_p_myStructArray_EventDataPort(),
          api_p_myArrayInt32_DataPort: s.get_producer_producer_p_myArrayInt32_DataPort(),
          api_p_myArrayStruct_DataPort: s.get_producer_producer_p_myArrayStruct_DataPort(),
          api_p_myStructArray_DataPort: s.get_producer_producer_p_myStructArray_DataPort(),
        };
        if let Some(pre) = &self.pre_producer_producer {
          if self.excuse_post_on_failed_pre && !self.pre_ok_producer_producer {
            out.report(crate::Event::CepPostExcused { thread: "producer_producer" });
          } else if !crate::gumbox::producer_producer_GUMBOX::compute_CEP_Post(
            post.api_p_myArrayInt32_EventDataPort, post.api_p_myArrayStruct_EventDataPort, post.api_p_myStructArray_EventDataPort, post.api_p_myArrayInt32_DataPort, post.api_p_myArrayStruct_DataPort, post.api_p_myStructArray_DataPort) {
            out.report(crate::Event::CepPostViolation { thread: "producer_producer", pre: pre, post: &post });
          }
        } else {
          out.report(crate::Event::CepPostSkipped { thread: "producer_producer" });
        }
      }
      crate::Thread::consumer_consumer => {
        let post = PostState_consumer_consumer {
          myArrayInt32_StateVar: s.get_consumer_consumer_sv_myArrayInt32_StateVar(),
          myArrayStruct_StateVar: s.get_consumer_consumer_sv_myArrayStruct_StateVar(),
          myStructArray_StateVar: s.get_consumer_consumer_sv_myStructArray_StateVar(),
        };
        if let Some(pre) = &self.pre_consumer_consumer {
          if self.excuse_post_on_failed_pre && !self.pre_ok_consumer_consumer {
            out.report(crate::Event::CepPostExcused { thread: "consumer_consumer" });
          } else if !crate::gumbox::consumer_consumer_GUMBOX::compute_CEP_Post(
            pre.In_myArrayInt32_StateVar, pre.In_myArrayStruct_StateVar, pre.In_myStructArray_StateVar, post.myArrayInt32_StateVar, post.myArrayStruct_StateVar, post.myStructArray_StateVar, pre.api_c_myArrayInt32_EventDataPort, pre.api_c_myArrayStruct_EventDataPort, pre.api_c_myStructArray_EventDataPort, pre.api_c_myArrayInt32_DataPort, pre.api_c_myArrayStruct_DataPort, pre.api_c_myStructArray_DataPort) {
            out.report(crate::Event::CepPostViolation { thread: "consumer_consumer", pre: pre, post: &post });
          }
        } else {
          out.report(crate::Event::CepPostSkipped { thread: "consumer_consumer" });
        }
      }
      _ => {}
    }
  }

  /// `next` is about to be dispatched: save its pre-state and check its CEP_Pre.
  pub fn on_dispatch<V: SystemView, S: ViolationSink>(&mut self, next: crate::Thread, s: &mut V, out: &mut S) {
    match next {
      crate::Thread::producer_producer => {
        let pre = PreState_producer_producer {
        };
        self.pre_ok_producer_producer = true;
        self.pre_producer_producer = Some(pre);
      }
      crate::Thread::consumer_consumer => {
        let pre = PreState_consumer_consumer {
          In_myArrayInt32_StateVar: s.get_consumer_consumer_sv_myArrayInt32_StateVar(),
          In_myArrayStruct_StateVar: s.get_consumer_consumer_sv_myArrayStruct_StateVar(),
          In_myStructArray_StateVar: s.get_consumer_consumer_sv_myStructArray_StateVar(),
          api_c_myArrayInt32_EventDataPort: s.get_producer_producer_p_myArrayInt32_EventDataPort(),
          api_c_myArrayStruct_EventDataPort: s.get_producer_producer_p_myArrayStruct_EventDataPort(),
          api_c_myStructArray_EventDataPort: s.get_producer_producer_p_myStructArray_EventDataPort(),
          api_c_myArrayInt32_DataPort: s.get_producer_producer_p_myArrayInt32_DataPort(),
          api_c_myArrayStruct_DataPort: s.get_producer_producer_p_myArrayStruct_DataPort(),
          api_c_myStructArray_DataPort: s.get_producer_producer_p_myStructArray_DataPort(),
        };
        if !crate::gumbox::consumer_consumer_GUMBOX::compute_CEP_Pre(
          pre.In_myArrayInt32_StateVar, pre.In_myArrayStruct_StateVar, pre.In_myStructArray_StateVar, pre.api_c_myArrayInt32_EventDataPort, pre.api_c_myArrayStruct_EventDataPort, pre.api_c_myStructArray_EventDataPort, pre.api_c_myArrayInt32_DataPort, pre.api_c_myArrayStruct_DataPort, pre.api_c_myStructArray_DataPort) {
          out.report(crate::Event::CepPreViolation { thread: "consumer_consumer", pre: &pre });
          self.pre_ok_consumer_consumer = false;
        } else {
          self.pre_ok_consumer_consumer = true;
        }
        self.pre_consumer_consumer = Some(pre);
      }
      _ => {}
    }
  }
}
